package com.crm.hr;
import com.crm.hr.entity.*;import com.crm.hr.repository.LeaveBalanceRepository.RequestDays;import com.crm.hr.service.*;import java.time.LocalDate;import java.math.BigDecimal;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
class LeaveBalanceCalculationTest {
 static final LocalDate FROM=LocalDate.parse("2026-01-01"),TO=LocalDate.parse("2026-12-31");
 static RequestDays row(long id,String from,String to,LeaveRequest.LeaveStatus status){return new RequestDays(){public Long getId(){return id;}public LocalDate getStartDate(){return LocalDate.parse(from);}public LocalDate getEndDate(){return LocalDate.parse(to);}public LeaveRequest.LeaveStatus getStatus(){return status;}};}
 static LeaveQuota quota(){var q=new LeaveQuota();q.setId(1L);q.setEmployeeId("101");q.setPeriodStart(FROM);q.setPeriodEnd(TO);q.setLeaveType("ANNUAL");q.setGrantedDays(new BigDecimal("20.50"));return q;}
 static LeaveBalanceCalculator.Balance calculate(RequestDays...rows){return LeaveBalanceCalculator.calculate("101",FROM,TO,List.of(quota()),List.of(rows));}
 @Test void emptyRequestsKeepExplicitGrant(){var b=calculate();assertEquals(new BigDecimal("20.50"),b.remainingDays());assertEquals(0,b.consumedDays());assertEquals("TECHNICAL_BALANCE",b.state());}
 @Test void approvedConsumedPendingSeparateAndRejectedExcluded(){var b=calculate(row(1,"2026-01-01","2026-01-03",LeaveRequest.LeaveStatus.APPROVED),row(2,"2026-02-01","2026-02-02",LeaveRequest.LeaveStatus.PENDING),row(3,"2026-03-01","2026-03-20",LeaveRequest.LeaveStatus.REJECTED));assertEquals(3,b.consumedDays());assertEquals(2,b.pendingDays());assertEquals(new BigDecimal("17.50"),b.remainingDays());assertEquals(new BigDecimal("15.50"),b.availableAfterPending());assertEquals(3,b.requests().size());}
 @Test void sameDayIsInclusive(){assertEquals(1,calculate(row(1,"2026-01-01","2026-01-01",LeaveRequest.LeaveStatus.APPROVED)).consumedDays());}
 @Test void weekendIsNotSilentlyWorkingDayPolicy(){assertEquals(2,calculate(row(1,"2026-01-03","2026-01-04",LeaveRequest.LeaveStatus.APPROVED)).consumedDays());}
 @Test void overlappingApprovedAndPendingDatesAreCountedOnce(){var b=calculate(row(1,"2026-01-01","2026-01-03",LeaveRequest.LeaveStatus.APPROVED),row(2,"2026-01-02","2026-01-04",LeaveRequest.LeaveStatus.APPROVED),row(3,"2026-01-03","2026-01-06",LeaveRequest.LeaveStatus.PENDING),row(4,"2026-01-05","2026-01-07",LeaveRequest.LeaveStatus.PENDING));assertEquals(4,b.consumedDays());assertEquals(3,b.pendingDays());assertTrue(b.overlapsDetected());}
 @Test void adjacentDaysDoNotReportAnOverlap(){var b=calculate(row(1,"2026-01-01","2026-01-02",LeaveRequest.LeaveStatus.APPROVED),row(2,"2026-01-03","2026-01-04",LeaveRequest.LeaveStatus.APPROVED));assertEquals(4,b.consumedDays());assertFalse(b.overlapsDetected());}
 @Test void crossPeriodRequestsAreClippedNotChargedTwice(){var b=calculate(row(1,"2025-12-30","2026-01-02",LeaveRequest.LeaveStatus.APPROVED),row(2,"2026-12-30","2027-01-03",LeaveRequest.LeaveStatus.APPROVED));assertEquals(4,b.consumedDays());assertEquals(FROM,b.requests().getFirst().from());assertEquals(TO,b.requests().getLast().to());}
 @Test void quotaMissingDoesNotInventZeroBalance(){var b=LeaveBalanceCalculator.calculate("101",FROM,TO,List.of(),List.of());assertNull(b.grantedDays());assertNull(b.remainingDays());assertEquals("NO_QUOTA",b.state());}
 @Test void partialQuotaIsNotProrated(){var q=quota();q.setPeriodEnd(TO.minusDays(1));var b=LeaveBalanceCalculator.calculate("101",FROM,TO,List.of(q),List.of());assertEquals("QUOTA_PERIOD_MISMATCH",b.state());assertNull(b.remainingDays());}
 @Test void multipleTypesDoNotProduceAnInventedAllocation(){var q=quota();var other=quota();other.setId(2L);other.setLeaveType("OTHER");var b=LeaveBalanceCalculator.calculate("101",FROM,TO,List.of(q,other),List.of());assertEquals("QUOTA_TYPE_AMBIGUOUS",b.state());assertNull(b.remainingDays());}
 @Test void negativeRemainingIsReportedWithoutClamping(){var q=quota();q.setGrantedDays(BigDecimal.ZERO);var b=LeaveBalanceCalculator.calculate("101",FROM,TO,List.of(q),List.of(row(1,"2026-01-01","2026-01-01",LeaveRequest.LeaveStatus.APPROVED)));assertEquals(new BigDecimal("-1"),b.remainingDays());}
 @Test void leapDayIsOneCivilDay(){var b=LeaveBalanceCalculator.calculate("101",LocalDate.parse("2028-02-28"),LocalDate.parse("2028-03-01"),List.of(),List.of(row(1,"2028-02-28","2028-03-01",LeaveRequest.LeaveStatus.APPROVED)));assertEquals(3,b.consumedDays());}
 @Test void invalidRangeAndOversizedPeriodAreRejected(){assertThrows(IllegalArgumentException.class,()->HrPeriod.require(TO,FROM));assertThrows(IllegalArgumentException.class,()->HrPeriod.require(FROM,TO.plusDays(2)));}
}